  const tone=n=>n<0?'bt-down':n>0?'bt-up':'';
  const pf=n=>n===Infinity?'∞':num(n);
  let key='onepercent:backtesting:v1:guest', owner='Guest', state={sessions:[],strategies:[]};
  let active=null, timer=null, speed=1, barsVisible=80, movingAverage=false, lineTool=false, chartView=null, saveBlocked=false;
  let dateFilter='all',tradeTab='closed',tradeFilter='all',tradeSort='newest',analyticsYear=null,challengeDraft=null;
  let query='', sort='newest', instrument='', layout='grid', toastTimer, busy=false, ready=false;
  const localMT5=location.hostname==='localhost' && location.port==='8765';
  let brokerPairs=[], sharedPairs=[], sync=null, ownerGeneration=0;
