    const lo=Math.min(...points,s.startBalance),hi=Math.max(...points,s.startBalance), span=hi-lo||s.startBalance*.01||1;
    const path=points.map((v,i)=>(i?'L':'M')+(i/Math.max(1,points.length-1)*400).toFixed(1)+','+(74-(v-lo)/span*58).toFixed(1)).join(' ');
