   $('#bt-undo-drawing').onclick=()=>chartView.undo();$('#bt-delete-drawing').onclick=()=>{if(!chartView.deleteSelected())toast('Select a chart drawing first.');};
   for(const b of document.querySelectorAll('[data-draw-tool]'))b.onclick=()=>{lineTool=false;if(chartView.tool(b.dataset.drawTool)===false)return;for(const x of document.querySelectorAll('[data-draw-tool]'))x.classList.toggle('active',x===b);$('#bt-line').classList.remove('active');if(b.dataset.drawTool!=='cursor'){const d=window.BacktestDrawingSuite.spec(b.dataset.drawTool);toast(['brush','highlighter'].includes(d.id)?'Drag on the chart to draw '+d.label:!d.points?'Click points, then double-click to finish '+d.label:d.points===1?'Click the chart to place '+d.label:'Click '+d.points+' anchor points for '+d.label);}};
   $('#bt-rules').onclick=()=>{const rules=s.strategySnapshot;modal('Session rules',rules?'<h3>'+esc(rules.name)+'</h3><p>'+esc(rules.description||'Frozen when this session was created.')+'</p>'+((rules.checklist||[]).length?'<div class="bt-session-checklist">'+rules.checklist.map((x,i)=>'<label><input type="checkbox" data-checklist-index="'+i+'" '+((s.checklist||[]).includes(i)?'checked':'')+'> '+esc(x)+'</label>').join('')+'</div>':'')+['setup','entry','exit','risk'].filter(k=>rules[k]).map(k=>'<h4>'+k.toUpperCase()+'</h4><p>'+esc(rules[k])+'</p>').join(''):'<p>No strategy was assigned. Add your hypothesis to the session notes.</p>');for(const box of document.querySelectorAll('[data-checklist-index]'))box.onchange=()=>{s.checklist=[...document.querySelectorAll('[data-checklist-index]:checked')].map(x=>Number(x.dataset.checklistIndex));persist();};};
