  function reviewTrade(s,index){const t=s.trades[index];if(!t)return;const key=E.tradeKey(t),review=s.reviews?.[key]||{},emotions=[['confident','😀'],['calm','🙂'],['neutral','😐'],['anxious','😟'],['frustrated','😠']];modal('Trade review','<div class="bt-review-outcome '+tone(t.pnl)+'"><span>'+esc(t.reason)+'</span><b>'+cash(t.pnl)+'</b></div><div class="bt-review-metrics">'+[['Entry price',price(t.entry)],['Exit price',price(t.exit)],['Duration',num((t.exitTime-t.entryTime)/3600,1)+'h'],['Initial risk',cash(t.riskCash)]].map(([k,v])=>'<div><small>'+k+'</small><b>'+v+'</b></div>').join('')+'</div>'+miniTradeChart(E.marketData(s,t.symbol)||s,t)+'<form id="bt-review-form"><label class="bt-field"><span>Notes</span><textarea name="notes" class="bt-textarea" rows="3" maxlength="4000" placeholder="What did you learn from this trade?">'+esc(review.notes||'')+'</textarea></label><fieldset class="bt-emotions"><legend>Emotion</legend>'+emotions.map(([id,icon])=>'<label><input name="emotion" type="radio" value="'+id+'" '+((review.emotion||'neutral')===id?'checked':'')+'><span title="'+id+'" aria-label="'+id+'">'+icon+'</span></label>').join('')+'</fieldset><div class="bt-actions"><button class="bt-button" type="button" data-close-dialog>Discard</button><button class="bt-button primary" type="submit">Save review</button></div></form>');$('#bt-review-form').onsubmit=e=>{e.preventDefault();s.reviews??={};s.reviews[key]=Object.fromEntries(new FormData(e.currentTarget));persist();$('#bt-dialog').close();if(current())updateSession();toast('Trade review saved.');};}
  function miniTradeChart(s,t){const raw=s.candles.filter(b=>b.t<=t.exitTime),entry=Math.max(0,raw.findIndex(b=>b.t>=t.entryTime)-8),bars=raw.slice(entry).slice(-80);if(!bars.length)return '';const lo=Math.min(...bars.map(b=>b.l)),hi=Math.max(...bars.map(b=>b.h)),span=hi-lo||1,y=p=>180-(p-lo)/span*160,x=i=>20+i*360/Math.max(1,bars.length-1);return '<svg viewBox="0 0 400 205" class="bt-trade-preview" role="img" aria-label="Historical candles up to this trade’s exit"><rect width="400" height="205" fill="#15171c"/>'+bars.map((b,i)=>'<path d="M'+x(i)+' '+y(b.h)+'V'+y(b.l)+'M'+(x(i)-1.5)+' '+y(b.o)+'H'+(x(i)+1.5)+'V'+y(b.c)+'H'+(x(i)-1.5)+'Z" stroke="'+(b.c>=b.o?'#45d5a2':'#ff7484')+'" fill="'+(b.c>=b.o?'#45d5a2':'#ff7484')+'"/>').join('')+[[t.stop,'#ff7484','SL'],[t.target,'#45d5a2','TP'],[t.entry,'#9aabc2','Entry']].filter(([p])=>y(p)>=15&&y(p)<=190).map(([p,c,l])=>'<path d="M10 '+y(p)+'H390" stroke="'+c+'" stroke-dasharray="4 4"/><text x="12" y="'+(y(p)-4)+'" fill="'+c+'" font-size="9">'+l+'</text>').join('')+'</svg>';}
  function indicators(){const s=current();if(!s)return;const Studies=window.BacktestStudies;modal('Indicators','<input id="bt-indicator-search" class="bt-input" type="search" placeholder="Search" aria-label="Search indicators"><div class="bt-study-caption">SCRIPT NAME</div><div id="bt-indicator-list">'+Studies.definitions.map(({id,label})=>{const why=Studies.unavailable(id,s.candles.slice(0,s.cursor+1));return '<label class="bt-indicator-option" title="'+esc(why||label)+'"><input type="checkbox" value="'+id+'" '+((s.indicators||[]).includes(id)?'checked':'')+' '+(why?'disabled':'')+'><span>'+esc(label)+(why?'<small>'+esc(why)+'</small>':'')+'</span></label>';}).join('')+'</div>');$('#bt-indicator-search').oninput=e=>{for(const row of $('#bt-indicator-list').children)row.hidden=!row.textContent.toLowerCase().includes(e.target.value.toLowerCase());};$('#bt-indicator-list').onchange=()=>{s.indicators=[...$('#bt-indicator-list').querySelectorAll('input:checked:not(:disabled)')].map(x=>x.value);persist();drawChart();};}
  function challenges(){
   const models=[{name:'One-step practice',targetPct:10,dailyLossPct:3,maxLossPct:6,minDays:3,trailing:false},{name:'Two-step · phase 1',targetPct:8,dailyLossPct:5,maxLossPct:10,minDays:5,trailing:false},{name:'Two-step · phase 2',targetPct:5,dailyLossPct:5,maxLossPct:10,minDays:5,trailing:false},{name:'Trailing drawdown',targetPct:10,dailyLossPct:3,maxLossPct:6,minDays:5,trailing:true}];let model=0,balance=10000;
   app.innerHTML=workspaceHeader('Practice challenges','challenges')+'<div class="bt-toolbar"><p class="bt-local-note" style="margin:0">Simulated practice rules · no purchase or funded account</p>'+workspaceTabs('challenges')+'</div><div class="bt-challenge-layout"><section class="bt-panel"><h3>Select model</h3><div class="bt-actions" id="bt-challenge-models">'+models.map((m,i)=>'<button class="bt-button '+(i===0?'primary':'')+'" data-model="'+i+'">'+esc(m.name)+'</button>').join('')+'</div><h3>Select account size</h3><div class="bt-actions" id="bt-challenge-sizes">'+[5000,10000,25000,50000,100000,200000,300000,400000].map(n=>'<button class="bt-button '+(n===10000?'primary':'')+'" data-balance="'+n+'">'+n/1000+'K</button>').join('')+'</div><p class="bt-local-note">These are TheOnePercent study presets, not the terms of any prop firm. Loss limits are checked on revealed candle-close equity. Review the rules before starting.</p></section><aside class="bt-panel" id="bt-challenge-summary"></aside></div><h2 class="bt-subheading">Your past challenges</h2><div id="bt-past-challenges" class="bt-grid"></div>';
   function render(){const m=models[model];$('#bt-challenge-summary').innerHTML='<h2>'+esc(m.name)+'</h2><p class="bt-meta">'+cash(balance)+' · simulated account</p><dl class="bt-rule-list">'+[['Profit target',m.targetPct+'%'],['Daily loss limit',m.dailyLossPct+'% of starting balance'],['Max loss ('+(m.trailing?'trailing':'static')+')',m.maxLossPct+'%'],['Minimum trading days',m.minDays],['Time limit','Dataset end']].map(([k,v])=>'<div><dt>'+k+'</dt><dd>'+v+'</dd></div>').join('')+'</dl><button class="bt-button primary" id="bt-start-challenge">Start practice challenge</button>';$('#bt-start-challenge').onclick=()=>{sessionForm();challengeDraft={...m};$('#bt-new-form').elements.startBalance.value=balance;$('#bt-new-form').elements.name.value=m.name;toast('Choose a dataset to start this practice challenge.');};}render();
   $('#bt-challenge-models').onclick=e=>{const b=e.target.closest('[data-model]');if(!b)return;model=Number(b.dataset.model);for(const x of $('#bt-challenge-models').children)x.classList.toggle('primary',x===b);render();};$('#bt-challenge-sizes').onclick=e=>{const b=e.target.closest('[data-balance]');if(!b)return;balance=Number(b.dataset.balance);for(const x of $('#bt-challenge-sizes').children)x.classList.toggle('primary',x===b);render();};const past=state.sessions.filter(s=>s.challenge);$('#bt-past-challenges').innerHTML=past.length?past.map(card).join(''):'<p class="bt-local-note">You haven’t run any practice challenges yet.</p>';
  }
  function workspaceHeader(title,section){return '<header class="bt-heading"><div><h1>'+title+'</h1></div><div class="bt-actions"><div class="bt-view" aria-label="Layout"><button data-layout="grid" class="'+(layout==='grid'?'active':'')+'">▦ Grid</button><button data-layout="list" class="'+(layout==='list'?'active':'')+'">☷ List</button></div><button class="bt-button primary" data-new-session>＋ New session</button><button class="bt-button" data-new-strategy>＋ New strategy</button></div></header>';}
  function workspaceTabs(section){return '<nav class="bt-tabs bt-workspace-tabs" aria-label="Research sections">'+[['sessions','▥ Sessions'],['strategies','⌘ Strategies'],['challenges','♜ Challenges']].map(([id,label])=>'<a href="#'+id+'" class="'+(section===id?'active':'')+'">'+label+'</a>').join('')+'</nav>';}
  function tutorial(){return '<article class="bt-card bt-tutorial"><h2>Tutorial</h2><p>Watch how to get started</p><button class="bt-tutorial-media" data-guide aria-label="Play backtesting tutorial"><img src="'+ROOT+'assets/backtesting/tutorial-preview.svg" alt="Historical EURUSD candle replay preview"><span>▶</span></button></article>';}
  function filtered(){const cutoff=dateFilter==='30'?Date.now()-30*86400000:dateFilter==='7'?Date.now()-7*86400000:0;return state.sessions.filter(s=>(!instrument||s.symbol===instrument||s.markets?.some(m=>m.symbol===instrument))&&(!cutoff||Date.parse(s.createdAt)>=cutoff)&&(s.name+' '+s.symbol+' '+sessionStrategy(s)).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='return'?E.metrics(b).returnPct-E.metrics(a).returnPct:sort==='oldest'?a.createdAt.localeCompare(b.createdAt):b.createdAt.localeCompare(a.createdAt));}
  function card(s){const m=E.metrics(s),progress=Math.round(s.markets?s.markets.reduce((n,m)=>n+m.cursor-m.initialCursor,0)/s.markets.reduce((n,m)=>n+m.candles.length-1-m.initialCursor,0)*100:(s.cursor-s.initialCursor)/(s.candles.length-1-s.initialCursor)*100),challenge=E.challengeState(s);return '<article class="bt-card"><div class="bt-card-inner"><div class="bt-card-top"><div><h2>'+esc(s.name)+'</h2><div class="bt-meta">'+esc(s.symbol)+(s.markets?' + '+(s.markets.length-1):'')+' · '+date(s.candles[s.initialCursor].t).slice(0,10)+'</div></div><div class="bt-card-actions"><button class="bt-button small bt-continue" data-open="'+esc(s.id)+'">▶ Continue</button><button class="bt-button small bt-stats-button" data-stats="'+esc(s.id)+'">▥ Stats</button><details class="bt-more"><summary aria-label="Session actions">⋮</summary><div><button data-export-trades="'+esc(s.id)+'">Export trades</button><button data-delete-session="'+esc(s.id)+'">Delete session</button></div></details></div></div><div class="bt-card-return '+tone(m.returnPct)+'">'+pct(m.returnPct)+' <span class="bt-return-arrow">'+(m.returnPct<0?'↘':'↗')+'</span></div><div class="bt-card-money">'+cash(m.equity-s.startBalance)+'</div><div class="bt-card-metrics"><div><b>'+m.trades+'</b><small>TRADES</small></div><div><b class="'+(m.winRate!=null&&m.winRate>=50?'bt-up':m.winRate!=null?'bt-down':'')+'">'+(m.winRate==null?'—':num(m.winRate,0)+'%')+'</b><small>WIN</small></div><div><b class="'+(m.drawdown>0?'bt-down':'')+'">'+num(m.drawdown,1)+'%</b><small>DD</small></div><div><b>'+pf(m.profitFactor)+'</b><small>PF</small></div></div></div>'+spark(s)+'<div class="bt-outcomes"><span class="bt-up">● '+m.wins+'</span><span class="bt-down">● '+m.losses+'</span><span>● '+m.breakeven+'</span>'+(challenge?'<b class="bt-challenge-badge '+challenge.status+'">'+esc(challenge.status)+'</b>':'')+'</div><small class="bt-card-source">'+esc(s.source)+'</small><div class="bt-card-foot"><span>'+progress+'% replayed</span><span>'+esc(sessionStrategy(s))+'</span></div></article>';}
  function renderCards() { $('#bt-cards').innerHTML=(layout==='grid'?tutorial():'')+filtered().map(card).join('')+(!filtered().length?'<div class="bt-empty"><h2>'+ (state.sessions.length?'No matching sessions':'Your research starts here')+'</h2><p>'+(state.sessions.length?'Try a different search or instrument.':'Create a session from an archived dataset or your own OHLC CSV. No results are prefilled.')+'</p><button class="bt-button primary" data-new-session>＋ New session</button></div>':''); }
  function dashboard(){app.innerHTML=workspaceHeader('Your sessions','sessions')+'<div class="bt-toolbar"><div class="bt-filters"><input id="bt-search" class="bt-input" type="search" aria-label="Search sessions" placeholder="⌕  Search…" value="'+esc(query)+'"><select id="bt-sort" class="bt-select" aria-label="Sort sessions"><option value="newest">Newest</option><option value="oldest">Oldest</option><option value="name">Name A–Z</option><option value="return">Highest return</option></select><select id="bt-date-filter" class="bt-select" aria-label="Date filter"><option value="all">All time</option><option value="30">Last 30 days</option><option value="7">Last 7 days</option></select><select id="bt-instrument" class="bt-select" aria-label="Filter instrument"><option value="">Instruments</option>'+[...new Set(state.sessions.flatMap(s=>s.markets?s.markets.map(m=>m.symbol):[s.symbol]))].map(x=>'<option>'+esc(x)+'</option>').join('')+'</select></div>'+workspaceTabs('sessions')+'</div><div id="bt-cards" class="bt-grid '+(layout==='list'?'list':'')+'"></div><p class="bt-local-note">Historical replay · simulated trades. Sample archives work on phone and PC without MT5. Sign in to save your account workspace online.</p>';
   $('#bt-sort').value=sort;$('#bt-instrument').value=instrument;$('#bt-date-filter').value=dateFilter;$('#bt-search').oninput=e=>{query=e.target.value;renderCards();};$('#bt-sort').onchange=e=>{sort=e.target.value;renderCards();};$('#bt-instrument').onchange=e=>{instrument=e.target.value;renderCards();};$('#bt-date-filter').onchange=e=>{dateFilter=e.target.value;renderCards();};renderCards();}
