    async function loadCloud(auto=false){const status=$('#bt-cloud-status');status.textContent='Checking downloaded history…';try{const user=await window.Cloud?.ready;if(!user?.id)throw Error('Sign in to use downloaded history.');if(!cloudLoaded){cloudArchives=await cloudHistory.catalog();cloudLoaded=true;}if(!form.isConnected)return;const selected=$('#bt-cloud-archive').value;$('#bt-cloud-archive').innerHTML=cloudArchives.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.symbol+' · '+x.interval+' · '+x.provider)+'</option>').join('')||'<option value="">No archives available for this account</option>';$('#bt-cloud-archive').value=cloudArchives.some(x=>x.id===selected)?selected:cloudArchives.find(x=>x.symbol==='EURUSD'&&x.timeframe==='H1')?.id||cloudArchives[0]?.id||'';if(!cloudArchives.length)status.textContent='No downloaded history is assigned to this account. Included archives and CSV imports are available under Choose other history.';else if(auto&&!sourceChanged&&datasets.some(x=>x.id===form.elements.dataset.value)){form.elements.dataset.value='cloud';form.elements.dataset.dispatchEvent(new Event('change'));}else if(form.elements.dataset.value==='cloud')selectCloud();}catch(error){if(form.isConnected){$('#bt-cloud-archive').innerHTML='<option value="">Unavailable</option>';status.textContent=error.message;}}}
