    async function loadExtras(f){
      const checks=[...$('#bt-extra-options').querySelectorAll('[data-extra-pair]:checked')],rows=[];
      for(const box of checks){
        const key=box.dataset.extraPair,d=datasets.find(d=>d.id===key),conversion=box.dataset.quote==='USD'?1:Number([...$('#bt-extra-options').querySelectorAll('[data-extra-conversion]')].find(x=>x.dataset.extraConversion===key)?.value);
        if(!Number.isFinite(conversion)||conversion<=0)throw Error('Enter a fixed USD conversion for '+key+'.');
        if(f.get('dataset')==='cloud'){
          const primary=cloudArchives.find(x=>x.id===$('#bt-cloud-archive').value),archive=cloudArchives.find(x=>x.symbol===key&&x.timeframe===primary?.timeframe);
          if(!archive)throw Error('Choose a cloud pair with the same base timeframe.');
          const result=await cloudHistory.load(archive.id,{start:f.get('start'),end:f.get('end')});
          rows.push({...result,multiplier:conversion,fxMode:result.symbol.startsWith('USD')?'inverse':'fixed'});continue;
        }
        if(d){
          const response=await fetch(ROOT+'assets/backtesting/data/'+d.file);if(!response.ok)throw Error('Could not load '+d.symbol+' archive.');
          rows.push({...d,candles:E.parseCSV(await response.text()),source:d.source||'Archived sample · Yahoo Finance via project cache',multiplier:conversion});
        }else{
          const mt5=f.get('dataset')==='mt5',interval=mt5?$('#bt-broker-interval').value:$('#bt-shared-interval').value,body=mt5?await brokerJSON('/api/backtesting/candles?'+new URLSearchParams({symbol:key,interval,limit:$('#bt-broker-count').value})):await sharedJSON('/api/backtesting/candles?'+new URLSearchParams({symbol:key,interval,limit:$('#bt-shared-count').value,end:$('#bt-shared-end').value,start:window.BacktestFrames.historyStart(form.elements.start.value,$('#bt-shared-interval').value)}));
          if(body.symbol!==key||body.interval!==interval||!body.closed_only)throw Error('Unexpected pair in shared history.');
          rows.push({symbol:key,interval,source:body.source,multiplier:conversion,candles:E.validateBars(body.candles)});
        }
      }return rows;
    }

    let coverageGeneration=0;
