    function selectShared(){resetCoverage();const pair=sharedPairs.find(p=>p.symbol===$('#bt-shared-pair').value);if(!pair)return;form.elements.symbol.value=pair.symbol;form.elements.interval.value=$('#bt-shared-interval').value;form.elements.multiplier.value=pair.quote_asset==='USD'?'1':'';form.elements.multiplier.placeholder=pair.quote_asset==='USD'?'1':'Enter fixed USD conversion per price unit';if(pair.quote_asset!=='USD')advanced.open=true;extraChoices();}
    function filterShared(){const q=$('#bt-shared-search').value.toLowerCase();$('#bt-shared-pair').innerHTML=sharedPairs.filter(p=>p.symbol.toLowerCase().includes(q)).map(p=>'<option>'+esc(p.symbol)+'</option>').join('');selectShared();}
