    async function loadShared(){const status=$('#bt-shared-status');sharedPairs=[];try{const rows=[];let offset=0;while(true){const result=await sharedJSON('/api/backtesting/catalog?limit=100&offset='+offset);if(result.status!=='configured')throw Error(result.message || 'Shared forex history is not connected yet. Choose an included archive to preview.');rows.push(...result.data);if(!result.has_more)break;if(!result.data.length || offset>100000)throw Error('Incomplete provider catalogue.');offset+=result.data.length;}if(!form.isConnected)return;sharedPairs=rows;filterShared();status.textContent=rows.length+' forex pairs available. History coverage depends on the provider.';}catch(error){if(form.isConnected){$('#bt-shared-pair').innerHTML='<option value="">No shared pairs available</option>';status.textContent=error.message+' Included sample archives work without MT5.';}}}
