   const list=$('#bt-check-items');function add(text=''){if(list.children.length>=20)return toast('Maximum 20 checklist items.');const row=document.createElement('div');row.className='bt-check-item';row.innerHTML='<span>☐</span><input class="bt-input" name="checklistItem" maxlength="200" placeholder="e.g. Wait for the signal candle to close" value="'+esc(text)+'"><button type="button" class="bt-text-button" aria-label="Remove checklist item">✕</button>';row.querySelector('button').onclick=()=>row.remove();list.appendChild(row);}for(const x of existing?.checklist||[])add(x);$('#bt-add-check').onclick=()=>add();
